"""RFC-7807-style reporting for migrated Meridian CRM validation failures."""

_VALID_CODES = frozenset(
    f"E{group}{number:03d}"
    for group, last_number in (
        (1, 5),
        (2, 4),
        (3, 7),
        (4, 4),
        (5, 5),
    )
    for number in range(1, last_number + 1)
)


def problem_details(errors: list[dict]) -> dict:
    """Return the validation problem document for one attempted write."""
    for error in errors:
        if error["code"] not in _VALID_CODES:
            raise ValueError(f"Unknown legacy validation code: {error['code']}")

    blocked = any(error["severity"] == "BLOCK" for error in errors)

    return {
        "type": "https://meridian-crm.example/problems/validation",
        "title": "Legacy validation failed",
        "status": 422 if blocked else 200,
        "blocked": blocked,
        "errors": [
            {
                "code": error["code"],
                "message": error["message"],
                "severity": error["severity"],
            }
            for error in errors
        ],
    }
